    if (tableContainer) AppUtils.showLoading(tableContainer);

    try {
        const response = await AppUtils.apiRequest('/dashboard/idms-data');
        if (response.ok) {
            const data = await response.json();
            renderDataTable(data.data);
        }
    } catch (err) {
        console.error('Failed to load IDMS data', err);
    }
}

/**
 * Render data table with IDMS data
 * @param {Array} data
 */
function renderDataTable(data) {
    const container = document.getElementById('idms-table');
    if (!container) return;

    if (!data || data.length === 0) {
        container.innerHTML = '<p>No data available.</p>';
        return;
    }

    let html = '<table><thead><tr>';
    html += '<th>ID</th><th>Column 1</th><th>Column 2</th><th>Column 3</th><th>Column 4</th><th>Column 5</th>';
    html += '</tr></thead><tbody>';

    data.forEach(row => {
        html += `<tr>
            <td>${row.id}</td>
            <td>${row.column_1 || ''}</td>
            <td>${row.column_2 || ''}</td>
            <td>${row.column_3 || ''}</td>
            <td>${row.column_4 || ''}</td>
            <td>${row.column_5 || ''}</td>
        </tr>`;
    });

    html += '</tbody></table>';
    container.innerHTML = html;
}

/**
 * Load API usage statistics
 * @param {string} startDate
 * @param {string} endDate
 */
async function loadAPIUsageStats(startDate, endDate) {
    try {
        let url = '/dashboard/api-usage';
        const params = new URLSearchParams();
        if (startDate) params.set('start_date', startDate);
        if (endDate) params.set('end_date', endDate);
        if (params.toString()) url += '?' + params.toString();

        const response = await AppUtils.apiRequest(url);
        if (response.ok) {
            const stats = await response.json();
            renderAPIStats(stats);
        }

        // Also load breakdown
        let breakdownUrl = '/dashboard/api-usage/breakdown';
        if (params.toString()) breakdownUrl += '?' + params.toString();
        const breakdownResponse = await AppUtils.apiRequest(breakdownUrl);
        if (breakdownResponse.ok) {
            const breakdown = await breakdownResponse.json();
            renderAPIBreakdown(breakdown);
        }
    } catch (err) {
        console.error('Failed to load API usage stats', err);
    }
}

/**
