    const el = document.getElementById('api-total-calls');
    if (el) el.textContent = stats.total_calls;

    const rangeEl = document.getElementById('api-date-range');
    if (rangeEl) {
        rangeEl.textContent = `${AppUtils.formatDate(stats.start_date)} - ${AppUtils.formatDate(stats.end_date)}`;
    }
}

/**
 * Render API breakdown by page
 * @param {object} breakdown
 */
function renderAPIBreakdown(breakdown) {
    const container = document.getElementById('api-breakdown');
    if (!container) return;

    if (!breakdown.breakdown || breakdown.breakdown.length === 0) {
        container.innerHTML = '<p>No usage data for this period.</p>';
        return;
