 */
async function loadAuditLog(page = 1, pageSize = 20) {
    const container = document.getElementById('audit-log-table');
    if (container) AppUtils.showLoading(container);

    try {
        const response = await AppUtils.apiRequest(`/audit?page=${page}&page_size=${pageSize}`);
