function renderAuditLogTable(entries) {
    const container = document.getElementById('audit-log-table');
    if (!container) return;

    if (!entries || entries.length === 0) {
        container.innerHTML = '<p>No audit log entries found.</p>';
        return;
    }

    let html = '<table><thead><tr>';
    html += '<th>Timestamp</th><th>Action</th><th>Description</th><th>IP Address</th>';
    html += '</tr></thead><tbody>';

