}

/**
 * Load current user settings
 */
async function loadUserSettings() {
    try {
        const response = await AppUtils.apiRequest('/settings');
        if (response.ok) {
            const userData = await response.json();
            originalUserData = userData;
            populateSettingsForm(userData);
        }
    } catch (err) {
        console.error('Failed to load user settings', err);
    }
}

/**
 * Populate settings form with user data
 * @param {object} userData
 */
function populateSettingsForm(userData) {
    const fields = ['name', 'username', 'email', 'phone'];
    fields.forEach(field => {
        const el = document.getElementById(field);
        if (el) el.value = userData[field] || '';
    });

    const img = document.getElementById('profile-picture');
    if (img && userData.profile_picture) {
        img.src = `http://localhost:8000/uploads/profile_pictures/${userData.profile_picture}`;
    }
}

/**
 * Handle settings form submission
 * @param {Event} event
 */
async function handleSettingsSubmit(event) {
    event.preventDefault();
    const container = document.getElementById('settings-messages');
    AppUtils.clearMessages(container);

    const validation = validateSettingsForm();
    if (!validation.isValid) {
        displaySettingsMessage(validation.errors[0], 'error');
        return;
    }

    const body = {};
    ['name', 'username', 'email', 'phone'].forEach(field => {
        const val = document.getElementById(field)?.value?.trim();
        if (val !== undefined) body[field] = val || null;
    });

    try {
        const response = await AppUtils.apiRequest('/settings', {
            method: 'PUT',
            body: JSON.stringify(body),
        });
        if (response.ok) {
            const data = await response.json();
            originalUserData = data;
            populateSettingsForm(data);
            displaySettingsMessage('Settings updated successfully', 'success');
        } else {
            const err = await response.json();
            displaySettingsMessage(err.detail || 'Update failed', 'error');
        }
    } catch (err) {
        displaySettingsMessage('Failed to update settings', 'error');
    }
}

/**
 * Handle password form submission
 * @param {Event} event
 */
async function handlePasswordSubmit(event) {
    event.preventDefault();
    const container = document.getElementById('settings-messages');
    AppUtils.clearMessages(container);

    const validation = validatePasswordChange();
    if (!validation.isValid) {
        displaySettingsMessage(validation.errors[0], 'error');
        return;
    }

    const body = {
        current_password: document.getElementById('current-password')?.value,
        new_password: document.getElementById('new-password')?.value,
        confirm_password: document.getElementById('confirm-password')?.value,
    };

    try {
        const response = await AppUtils.apiRequest('/settings/password', {
            method: 'PUT',
            body: JSON.stringify(body),
        });
        if (response.ok) {
            displaySettingsMessage('Password updated successfully', 'success');
            document.getElementById('password-form')?.reset();
        } else {
            const err = await response.json();
            displaySettingsMessage(err.detail || 'Password update failed', 'error');
        }
    } catch (err) {
        displaySettingsMessage('Failed to change password', 'error');
    }
}

/**
 * Validate settings form
 * @returns {object}
 */
function validateSettingsForm() {
    const errors = [];
    const name = document.getElementById('name')?.value?.trim();
    const username = document.getElementById('username')?.value?.trim();
    const email = document.getElementById('email')?.value?.trim();

    if (!name) errors.push('Name is required');
    if (!username) errors.push('Username is required');
    if (!email) errors.push('Email is required');
    if (email && !email.includes('@')) errors.push('Invalid email format');

    return { isValid: errors.length === 0, errors };
}

/**
 * Validate password change fields
 * @returns {object}
 */
function validatePasswordChange() {
    const errors = [];
    const current = document.getElementById('current-password')?.value;
    const newPw = document.getElementById('new-password')?.value;
    const confirm = document.getElementById('confirm-password')?.value;

    if (!current) errors.push('Current password is required');
    if (!newPw) errors.push('New password is required');
    if (newPw && newPw.length < 8) errors.push('New password must be at least 8 characters');
    if (newPw !== confirm) errors.push('New passwords do not match');

    return { isValid: errors.length === 0, errors };
}

/**
