const NAV_ITEMS = [
    { name: 'Home', url: '/index.html', icon: 'home' },
    { name: 'Dashboard', url: '/dashboard.html', icon: 'dashboard' },
    { name: 'Audit Log', url: '/audit-log.html', icon: 'audit' },
];

/**
 * Initialize the navigation bar
 */
function initNavigation() {
    renderNavigationMenu();
    setActiveNavItem();
    initProfileIcon();

    const toggleBtn = document.getElementById('nav-toggle');
    if (toggleBtn) toggleBtn.addEventListener('click', toggleNavigation);

    window.addEventListener('resize', handleResize);
}

/**
 * Render navigation menu items
 */
function renderNavigationMenu() {
    const nav = document.getElementById('nav-menu');
    if (!nav) return;

    nav.innerHTML = '';
    NAV_ITEMS.forEach(item => {
        const a = document.createElement('a');
        a.href = item.url;
        a.className = 'nav-link';
        a.textContent = item.name;
        a.addEventListener('click', handleNavClick);
        nav.appendChild(a);
    });
}

/**
 * Toggle navigation bar collapsed/expanded state
 */
function toggleNavigation() {
    const sidebar = document.getElementById('sidebar');
    if (sidebar) sidebar.classList.toggle('collapsed');

    const content = document.getElementById('main-content');
    if (content) content.classList.toggle('expanded');
}

/**
 * Set active navigation item based on current page
 */
function setActiveNavItem() {
    const path = window.location.pathname;
    const links = document.querySelectorAll('.nav-link');
    links.forEach(link => {
        if (link.getAttribute('href') === path) {
            link.classList.add('active');
        } else {
            link.classList.remove('active');
        }
    });
}

/**
 * Handle navigation link click
 * @param {Event} event
 */
function handleNavClick(event) {
    if (!AppUtils.isAuthenticated()) {
        event.preventDefault();
        window.location.href = '/login.html';
    }
